{"command":"cat package.json; cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function diff(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const changes = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) changes.push({ bs, be: i, ss, se: j })
  }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      flush()
      i++; j++
      bs = i; ss = j
    } else if (j >= m || (i < n && L[i + 1][j] >= L[i][j + 1])) {
      i++
    } else {
      j++
    }
  }
  flush()
  return changes
}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (!['merge', 'merge2', 'regions'].includes(mode)) fail('usage: cli.js merge|merge2|regions')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const l of lines) {
  if (l === '%%%') docs.push([])
  else docs[docs.length - 1].push(l)
}
if (docs.length !== 3) fail('expected three parts separated by %%%')
const [mine, base, theirs] = docs

const all = [
  ...diff(base, mine).map(c => ({ ...c, side: 0 })),
  ...diff(base, theirs).map(c => ({ ...c, side: 1 })),
].sort((a, b) => a.bs - b.bs || a.side - b.side)

const sides = [mine, theirs]
const out = []
let conflict = false
let pos = 0
let k = 0
const stable = (to) => {
  if (to > pos) {
    const seg = base.slice(pos, to)
    if (mode === 'regions') out.push(`stable ${seg.length}`)
    else out.push(...seg)
  }
}
while (k < all.length) {
  const start = all[k].bs
  let end = all[k].be
  const group = [all[k++]]
  while (k < all.length && all[k].bs <= end) {
    end = Math.max(end, all[k].be)
    group.push(all[k++])
  }
  stable(start)
  pos = end
  let res, label
  if (group.length === 1) {
    const g = group[0]
    res = sides[g.side].slice(g.ss, g.se)
    label = g.side === 0 ? 'mine' : 'theirs'
  } else {
    const repl = [0, 1].map(s => {
      const cs = group.filter(c => c.side === s)
      if (!cs.length) return base.slice(start, end)
      const minS = Math.min(...cs.map(c => c.bs))
      const maxE = Math.max(...cs.map(c => c.be))
      const first = cs[0], last = cs[cs.length - 1]
      return sides[s].slice(first.ss - (minS - start), last.se + (end - maxE))
    })
    const [a, b] = repl
    const baseSeg = base.slice(start, end)
    const eq = (x, y) => x.length === y.length && x.every((v, i) => v === y[i])
    if (eq(a, b)) { res = a; label = 'both' }
    else if (eq(a, baseSeg)) { res = b; label = 'theirs' }
    else if (eq(b, baseSeg)) { res = a; label = 'mine' }
    else {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${a.length} base=${baseSeg.length} theirs=${b.length}`)
      else {
        out.push('<<<<<<< mine', ...a)
        if (mode === 'merge') out.push('||||||| base', ...baseSeg)
        out.push('=======', ...b, '>>>>>>> theirs')
      }
      continue
    }
  }
  if (mode === 'regions') out.push(`${label} ${res.length}`)
  else out.push(...res)
}
stable(base.length)
process.stdout.write(out.map(l => l + '\n').join(''))
process.exitCode = conflict ? 1 : 0
